
INSERT INTO exec_knowledge_chunk (knowledge_id, chunk_index, page_number, content, content_length) VALUES
(3, 0, NULL, 'СТАТУС ДОКУМЕНТА: проектный материал (презентация-обоснование). Центр цифровизации и развития технологий контрольной деятельности (ЦЦиРТКД) на момент подготовки презентации ЕЩЁ НЕ СОЗДАН. Все указанные сотрудники являются потенциальными участниками будущего Центра, а не действующим штатом. Материал носит характер проектного предложения (экспертная оценка), а не подтверждения уже действующей организационной структуры. Владелец документа: Кузьменко А.В., Директор по цифровизации и развитию технологий внутреннего контроля. Организация: ПСБ, Департамент по работе с контрольно-надзорными органами и противодействия недобросовестным практикам (ДРКНОиПНП), руководитель — Суханов М.Л.', 683),

(3, 1, 1, 'СЛАЙД 1. Перспективная организационная структура ДРКНОиПНП. Департамент возглавляет Суханов М.Л. В его подчинении три направления: 1) Директор по цифровизации и развитию технологий внутреннего контроля — Кузьменко А.В. Под ним предлагается создать Центр цифровизации и развития технологий контрольной деятельности (ЦЦиРТКД, 5 ШЕ) — на схеме показан пунктиром как проектируемое подразделение. Предполагаемый состав: Могилевская Т.Н. (упр. эксп.), Дружинина Ю.А. (упр. эксп.), Беленький М.А. (рук. пр.), Грибенник Ю.В. (вед. спец.), Липатов К.Д. (мл. спец.). 2) Директор по повышению эффективности контрольно-надзорной деятельности — Игнатов Д.Б. В подчинении: Управление аналитической поддержки (УАП, 11 ШЕ, из них 3 ШЕ предполагается передать в ЦЦиРТКД) во главе с Дерибизовой А.В., и Центр сопровождения проверок (ЦСП, 7 ШЕ) во главе с Леонтьевой И.Г. 3) Директор по взаимодействию с контрольно-надзорными органами — Громова З.Е. В подчинении: Управление противодействия недобросовестным практикам (УПНП, 16 ШЕ, из них 2 ШЕ предполагается передать в ЦЦиРТКД) во главе с Тимофеевым В.О., и Центр мониторинга операций на финансовом рынке во главе с Гулямовой Т.В.', 1156),

(3, 2, 2, 'СЛАЙД 2. Предлагаемое решение. Предлагается: 1. Создать ЦЦиРТКД численностью 5 штатных единиц путём внутреннего перераспределения работников ДРКНОиПНП: 3 ШЕ из УАП и 2 ШЕ из УПНП. 2. Включить ЦСП в состав УАП. 3. Не вводить отдельную руководящую штатную единицу в ЦЦиРТКД — координацию его деятельности возложить на Кузьменко А.В. Реорганизация проводится без увеличения общей штатной численности ДРКНОиПНП и без увеличения числа руководящих должностей. Численность до и после реорганизации: Управление противодействия недобросовестным практикам: до 16, после 14. Управление аналитической поддержки (с учётом включения ЦСП): до 18, после 15. Центр цифровизации и развития технологий контрольной деятельности: до 0, после 5. Всего по Департаменту: до 34, после 34 (без изменений). Вывод: общая численность Департамента сохраняется — 34 ШЕ; ЦЦиРТКД соответствует нормативу — не менее 5 ШЕ; УАП и УПНП сохраняют численность выше установленного минимума — не менее 10 ШЕ; новые постоянные штатные единицы не создаются; новая руководящая должность не вводится.', 1070),

(3, 3, 3, 'СЛАЙД 3. Обоснование, преимущество и вывод. Ключевое обоснование: предлагаемая реорганизация не создаёт новое направление деятельности с нуля — она организационно закрепляет уже выполняемую работу и объединяет профильных сотрудников в одном подразделении. В действующей распределённой модели Кузьменко А.В. отвечает за результат, но сотрудники формально подчинены другим руководителям. Это создаёт: конкуренцию поручений и приоритетов; зависимость доступности сотрудников от решений других руководителей; сложность оперативного перераспределения ресурсов; несоответствие фактической работы установленным КПЭ; сложность объективной оценки вклада работников; размывание ответственности за конечный результат. Создание ЦЦиРТКД устраняет разрыв между ответственностью за результат и полномочиями по управлению необходимыми ресурсами. Основные преимущества: единое управление ресурсами; единая приоритизация; прозрачные КПЭ; персональная ответственность; концентрация компетенций; снижение координационных потерь; повышение мотивации; бюджетная нейтральность (без увеличения постоянной численности ДРКНОиПНП). Ключевой вывод: создание ЦЦиРТКД приводит организационную структуру в соответствие с фактически выполняемой деятельностью, при этом общая численность ДРКНОиПНП и количество руководящих должностей не увеличиваются.', 1257),

(3, 4, 4, 'СЛАЙД 4. SWOT-анализ. Сильные стороны: общая численность ДРКНОиПНП не увеличивается; новая руководящая должность не создаётся; нормативы численности подразделений соблюдаются; полномочия соответствуют ответственности; единые приоритеты, КПЭ и управление загрузкой; профильные компетенции собраны в одной команде. Слабые стороны: минимальная стартовая численность ЦЦиРТКД; ограниченный резерв постоянных ресурсов; зависимость от отдельных ключевых специалистов; необходимость перераспределить задачи в УАП и УПНП; необходимость организационного переходного периода. Возможности: формирование единого портфеля инициатив Блока ВК; повторное использование разработанных решений; накопление единой экспертизы и методологии; масштабирование команды за счёт проектного ФОТ; прозрачный учёт загрузки и результатов; повышение скорости реализации инициатив; формирование команды для внедрения ИИ в Блоке ВК. Угрозы: рост объёма задач без соответствующего проектного ресурса; перегрузка сотрудников ЦЦиРТКД; сопротивление организационным изменениям; нестабильность проектного финансирования; пересечение функций с другими подразделениями; ослабление отдельных направлений УАП и УПНП. Вывод: преимущества реорганизации превышают возможные ограничения.', 1189),

(3, 5, 5, 'СЛАЙД 5. Постоянный и проектный ресурс. Предлагается разделить ресурсы ЦЦиРТКД на два контура. Постоянное ядро: 5 штатных единиц; формируется внутренним переводом; не увеличивает общую постоянную численность ДРКНОиПНП; обеспечивает постоянные функции, координацию и управление портфелем инициатив, матричное взаимодействие в Блоке ВК, внедрение ИИ-технологий в процессы Блока ВК. Проектный ресурс: привлекается под утверждённые инициативы Блока ВК; финансируется за счёт предусмотренного проектного ФОТ; закрепляется за ЦЦиРТКД на период реализации соответствующих инициатив; используется для выполнения конкретного объёма работ и достижения установленных результатов; пересматривается по мере изменения портфеля инициатив. Вывод: постоянное ядро ЦЦиРТКД создаётся без увеличения общей штатной численности ДРКНОиПНП. Масштабирование команды осуществляется только под утверждённые инициативы и в пределах предусмотренного проектного ФОТ. Проектные ставки не увеличивают постоянную численность и напрямую связаны со сроками, бюджетом и результатами конкретных инициатив.', 1051),

(3, 6, 6, 'СЛАЙД 6. Команда ЦЦиРТКД и распределение ролей. ЦЦиРТКД объединяет взаимодополняющие компетенции полного цикла. Могилевская Т.Н. — Проектный аналитик / архитектор автоматизации: проработка инициатив, анализ процессов, требования, проектирование и внедрение решений. Дружинина Ю.А. — Специалист по контролю исполнения: контроль поручений Блока ВК, отчётность, мониторинг сроков и статусов. Беленький М.А. — Разработчик решений автоматизации / потенциальный разработчик ИИ-решений: разработка прикладных решений на Python, прототипирование, техническое сопровождение. Липатов К.Д. — Разработчик решений автоматизации / потенциальный разработчик ИИ-решений: разработка и сопровождение программных инструментов, автоматизация операций, обработка данных. Грибенник Ю.В. — Координатор внедрения и внутренних коммуникаций: организация совместной работы, получение доступов и ресурсов, развитие сообщества, сопровождение внедрения. Цепочка процесса: Дружинина Ю.А. — выявление потребностей → Могилевская Т.Н. — анализ и проектирование → Беленький М.А. и Липатов К.Д. — разработка → Грибенник Ю.В. — внедрение и коммуникации → Кузьменко А.В. — приоритизация, распределение ресурсов и контроль результата.', 1153),

(3, 7, 7, 'СЛАЙД 7. Планируемая загрузка сотрудников (предварительное распределение). Могилевская Т.Н.: основная деятельность 30%, проекты и развитие 50%, совместные задачи 15%, резерв 5%. Дружинина Ю.А.: загрузка определяется по результатам замера — нельзя искусственно устанавливать величину до фактического замера трудозатрат. Беленький М.А.: основная деятельность 20%, проекты и развитие 60%, совместные задачи 15%, резерв 5%. Липатов К.Д.: основная деятельность 20%, проекты и развитие 65%, совместные задачи 10%, резерв 5%. Грибенник Ю.В.: основная деятельность 40%, проекты и развитие 25%, совместные задачи 30%, резерв 5%. Вывод: пять работников не дублируют друг друга, а образуют единую команду полного цикла с понятным распределением персональной и совместной загрузки. Цепочка: потребность → анализ → проектирование → реализация → внедрение → оценка результата.', 866),

(3, 8, NULL, 'ВАЖНОЕ ОГРАНИЧЕНИЕ ДЛЯ ИНТЕРПРЕТАЦИИ В РАСЧЁТАХ КАБИНЕТА: наличие пяти потенциальных сотрудников и оргсхемы не означает, что Центр уже создан или укомплектован. Постоянная (5 ШЕ, целевая организационная модель) и проектная численность должны учитываться раздельно от расчётной функциональной потребности. До организационного решения о создании ЦЦиРТКД текущий фактический штат Центра — 0 ставок, а указанные 5 ШЕ — предлагаемое постоянное ядро, источник формирования которого — внутренний перевод из УАП (3 ШЕ) и УПНП (2 ШЕ), без увеличения общей численности ДРКНОиПНП. Расчётная функциональная потребность (4,35 ставки) и предлагаемое постоянное ядро (5 ШЕ) — разные показатели: разница (0,65 ставки) является организационным резервом постоянного ядра, а не текущим профицитом действующего Центра. Требуется отдельное организационное решение об утверждении структуры.', 861);
